formula:
delta:=CLOSE-REF(CLOSE,1); gain:=IF(delta>0,delta,0); loss:=IF(delta<0,-delta,0);
avgGain6:=SMA(gain,6,1); avgLoss6:=SMA(loss,6,1); rsi_6:100-100/(1+avgGain6/IF(avgLoss6=0,0.000000000001,avgLoss6)),COLORFACC15;
avgGain14:=SMA(gain,14,1); avgLoss14:=SMA(loss,14,1); rsi_14:100-100/(1+avgGain14/IF(avgLoss14=0,0.000000000001,avgLoss14)),COLOR3B82F6;
avgGain24:=SMA(gain,24,1); avgLoss24:=SMA(loss,24,1); rsi_24:100-100/(1+avgGain24/IF(avgLoss24=0,0.000000000001,avgLoss24)),COLOR8B5CF6;
TOOLTIP(rsi_6,'RSI6'),COLORFACC15; TOOLTIP(rsi_14,'RSI14'),COLOR3B82F6; TOOLTIP(rsi_24,'RSI24'),COLOR8B5CF6;
